const axios = require('axios');

async function getVideoInfo(url) {
  try {
    const response = await axios.post('https://vd.netus.ai/v1/video-info', {
      url: url
    }, {
      headers: {
        'Content-Type': 'application/json'
      }
    });

    const videoInfo = response.data.video_info;

    let message = `Judul Video: ${videoInfo.title}\n`;
    message += `Thumbnail: ${videoInfo.thumbnail}\n`;
    message += `Durasi: ${videoInfo.duration} detik\n`;
    message += `Platform: ${videoInfo.platform}\n`;
    message += `Nama Channel: ${videoInfo.channel_name}\n`;
    message += `URL Channel: ${videoInfo.channel_url}\n`;
    message += `Nama Uploader: ${videoInfo.uploader_name}\n`;
    message += `Tanggal Upload: ${videoInfo.upload_date}\n`;
    message += `Jumlah View: ${videoInfo.view_count}\n`;
    message += `Jumlah Like: ${videoInfo.like_count}\n`;
    message += `URL Webpage: ${videoInfo.webpage_url}\n\n`;
    message += `Format Video:\n`;

    videoInfo.video_formats.forEach(format => {
      message += `- ID: ${format.format_id}\n`;
      message += `  Ekstensi: ${format.extension}\n`;
      message += `  Resolusi: ${format.resolution}\n`;
      message += `  FPS: ${format.fps}\n`;
      message += `  Video Codec: ${format.video_codec}\n`;
      message += `  Audio Codec: ${format.audio_codec}\n`;
      message += `  Ukuran File: ${format.file_size} bytes\n`;
      message += `  Memiliki Audio: ${format.has_audio ? 'Ya' : 'Tidak'}\n`;
      message += `  Catatan: ${format.format_note}\n`;
    });

    return message;
  } catch (error) {
    return `Terjadi kesalahan saat mengambil informasi video: ${error.message}`;
  }
}

